import re

from moler.exceptions import ParsingDone, CommandFailure

__author__ = 'Michal Ernst, Tomasz Krol'
__copyright__ = 'Copyright (C) 2019-2022, Nokia'
__email__ = 'michal.ernst@nokia.com, tomasz.krol@nokia.com'

from ta_moler.cmd.hub.rfswcli.generichub import GenericHub


class Password(GenericHub):
    """Password command class."""

    def __init__(self, connection, new_password=None, encrypt_password=True, prompt=None, newline_chars=None,
                 runner=None, user=None, reset_to_default=False):
        """
        Password command.

        :param connection: moler connection to device, terminal when command is executed
        :param new_password: user new password
        :param user: user for change password[hubadmin/hubapp] - if not passed hubadmin is used by default.
        :param reset_to_default: flag True/False
        :param encrypt_password: If True then * will be in logs when password is sent, otherwise plain text
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Password, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                       runner=runner)
        self.encrypt_password = encrypt_password
        self.new_password = new_password
        self.user = user
        self.reset_to_default = reset_to_default

        self._new_password_sent = False
        self._new_password_again_sent = False

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        cmd = "password"
        if self.user:
            cmd = f"{cmd} {self.user}"
        if self.reset_to_default:
            cmd = f"{cmd} resetToDefault"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Parse the output of the command.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        try:
            self._parse_new_password(line)
            self._parse_new_password_again(line)
            self._parse_password_changed_successfully(line)
            self._parse_password_reset_successfully(line)
            self._parse_password_error(line)
        except ParsingDone:
            pass
        return super(Password, self).on_new_line(line, is_full_line)

    # Please input new password:
    _re_new_password = re.compile(r'Please input new password:')

    def _parse_new_password(self, line):
        """
        Detect new password prompt.

        :param line: Line from device.
        :return: None but raises ParsingDone if all required commands are sent.
        """
        if self._regex_helper.search_compiled(Password._re_new_password, line) and not self._new_password_sent:
            self.connection.sendline(data=self.new_password, encrypt=self.encrypt_password)
            self._new_password_sent = True
            raise ParsingDone

    # Please input new password again:
    _re_new_password_again = re.compile(r'Please input new password again:')

    def _parse_new_password_again(self, line):
        """
        Detect retype new password.

        :param line: Line from device.
        :return: None but raises ParsingDone if all required commands are sent.
        """
        if self._regex_helper.search_compiled(Password._re_new_password_again, line) and not self._new_password_again_sent:
            self.connection.sendline(data=self.new_password, encrypt=self.encrypt_password)
            self._new_password_again_sent = True
            raise ParsingDone

    # password changed successfully!
    _re_password_changed_successfully = re.compile(r'password changed successfully!')

    def _parse_password_changed_successfully(self, line):
        """
        Parse password changed successfully.

        :param line: Line from device.
        :return: None but raises ParsingDone if all required commands are sent.
        """
        if self._regex_helper.search_compiled(Password._re_password_changed_successfully, line):
            self.current_ret["PASSWORD_CHANGED"] = True

            raise ParsingDone

    # hubapp's password reset successfully!
    _re_password_reset_successfully = re.compile(r'.*password reset successfully!')

    def _parse_password_reset_successfully(self, line):
        """
        Parse password reset successfully.

        :param line: Line from device.
        :return: None but raises ParsingDone if all required commands are sent.
        """
        if self._regex_helper.search_compiled(Password._re_password_reset_successfully, line):
            self.current_ret["PASSWORD_RESET"] = True

            raise ParsingDone

    # passwd: Authentication token manipulation error
    _re_password_error = re.compile(r"(?P<ERROR>.*ERROR.*)", re.IGNORECASE)

    def _parse_password_error(self, line):
        """
        Parse error.

        :param line: Line from device.
        :return: None but raises ParsingDone if all required commands are sent.
        """
        if self._regex_helper.search_compiled(Password._re_password_error, line):
            self.set_exception(CommandFailure(self, f"Unexpected error: '{self._regex_helper.group('ERROR')}'"))

            raise ParsingDone


